css:
:root{--lg-base:#eeeeec;--lg-top:#f3f3f1;--lg-bottom:#e9e9e7;--lg-pane:color-mix(in srgb,#fafaf8 calc(var(--glass-opacity,80%) * .72),transparent);--lg-pop:#fafaf8;--lg-rim:#ffffffdc;--lg-line:#19191926;--lg-depth:#14141413;--lg-bubble:#ffffff65;--lg-glint:#ffffff99}
.dark{--lg-base:#191919;--lg-top:#232322;--lg-bottom:#191919;--lg-pane:color-mix(in srgb,#222221 calc(var(--glass-opacity,80%) * .65),transparent);--lg-pop:#272727;--lg-rim:#ffffff66;--lg-line:#ffffff17;--lg-depth:#00000026;--lg-bubble:#ffffff0e;--lg-glint:#ffffff1a}
[data-workspace-area="conversation"]{background:linear-gradient(180deg,var(--lg-top),var(--lg-bottom) 78%)!important}
.messages-timeline-scroll{background:transparent!important}
[data-slot="sidebar-inner"],[data-chat-header]{background:var(--lg-base)!important}
[data-slot="composer-host"],[data-user-message-bubble],[data-thread-details-card],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="dialog-popup"]{
 background:linear-gradient(155deg,var(--lg-glint) 0%,transparent 56%),var(--lg-pane)!important;
 backdrop-filter:blur(26px);border:1px solid var(--lg-line)!important;
 box-shadow:inset 0 1px var(--lg-rim),inset 1px 0 var(--lg-glint),inset 0 -1px #00000012,0 6px 20px var(--lg-depth)!important}
[data-slot="composer-host"]{border-radius:20px!important}
[data-user-message-bubble]{border-radius:16px!important;background:var(--lg-bubble)!important;backdrop-filter:none;box-shadow:inset 0 1px var(--lg-line)!important}
[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="dialog-popup"]{background-color:color-mix(in srgb,var(--lg-pop) var(--glass-opacity,80%),transparent)!important}
@media(prefers-reduced-transparency:reduce){[data-slot="composer-host"],[data-user-message-bubble],[data-thread-details-card],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="dialog-popup"]{background:var(--lg-pop)!important;backdrop-filter:none}}
/* Outgoing bubble color experiment */
:root{--lg-bubble:#d2ebe1}
.dark{--lg-bubble:#315e50d9}
